signatures:
type Generator struct {
	ID	string	`yaml:"id"`
	Path	string	`yaml:"path"`
	Prompt	string	`yaml:"prompt"`
}

type APIEntry struct {
	Key		string
	Signature	string
}

type Lockfile struct {
	Hash	string		`json:"hash"`
	Graph	canonGraph	`json:"graph"`
	APIs	lang.APISet	`json:"apis"`
}

type FromResult struct {
	From		string
	EmptyDiff	bool
}

type Repo struct {
	Root	string
	Bin	string
	Log	log.Logger
}

type Diff struct {
	AddedNodes	[]Node
	RemovedNodes	[]Node
	AddedEdges	[]Edge
	RemovedEdges	[]Edge
}

type Edge struct {
	From	string
	To	string
}

type Node struct {
	Key	string
	Label	string
	ID	string
}

type Extractor interface {
	Name() string
	Match(Snapshot) bool
	Extract(Snapshot) (graph.Graph, error)
	ExtractAPIs(Snapshot) (APISet, error)
}

type PackageAPI struct {
	Key		string
	Doc		string
	Signatures	[]string
}

type Snapshot struct {
	Rev	string
	Files	map[string][]byte
}

type Logger interface {
	Info(msg string)
	Debug(msg string)
}

type Writer struct {
	W	io.Writer
	Level	int
}

type Args struct {
	From	string	`json:"from,omitempty" jsonschema:"git revision for the left side of a drift comparison"`
	To	string	`json:"to,omitempty" jsonschema:"git revision to inspect"`
}

type Data struct {
	Graph	string
	APIs	string
	Diff	string
}
